            let mut opened = std::fs::File::open(&backup).unwrap();
            assert!(!owns_open_backup(root, &backup, &mut opened).unwrap());
            assert_eq!(remove_owned_backups(root, &selected).unwrap_err().code, ErrorCode::FileChanged);
