    #[test]
    fn legacy_final_and_interrupted_receipts_remain_recognized() {
        for pending_state in [None, Some(false), Some(true)] {
            let directory = tempfile::tempdir().unwrap();
            let root = directory.path();
            let backup = root.join("feed.json.broken");
            std::fs::write(&backup, b"legacy original").unwrap();
            if let Some(truncated_final) = pending_state {
                let pending = directory_for(root, true, true).unwrap().unwrap();
                std::fs::hard_link(&backup, pending.join("feed.json.broken")).unwrap();
                let mut old = receipt(&backup, b"legacy original").unwrap();
                old.version = LEGACY_VERSION;
                write_receipt(root, &pending, &old).unwrap();
                if truncated_final {
                    std::fs::write(root.join("inbox/feed-backups/feed.json.broken.json"), br#"{"format":"craft-anything.feed-backup","ver"#).unwrap();
                }
            } else {
                record(root, &backup, b"legacy original").unwrap();
            }
            assert_eq!(owned_backups(root).unwrap(), vec![backup.clone()]);
            assert_eq!(matching_copy(root, b"legacy original").unwrap(), Some(backup.clone()));
            remove_owned_backups(root, std::slice::from_ref(&backup)).unwrap();
            assert!(!backup.exists());
        }
    }

    #[test]
    fn absent_or_nonfile_backups_do_not_read_unrelated_receipts() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        let backup = root.join("feed.json.broken");
        let mut reads = 0;
        for with_directory in [false, true] {
            if with_directory {
                std::fs::create_dir(&backup).unwrap();
            }
            let owned = owned_backups_using(root, &mut || Ok(()), |_| {
                reads += 1;
                Err(ToolError::io("unrelated receipt", std::io::Error::from(std::io::ErrorKind::PermissionDenied)))
            })
            .unwrap();
            assert!(owned.is_empty());
            assert_eq!(reads, 0);
        }
        std::fs::remove_dir(&backup).unwrap();
        std::fs::write(&backup, b"personal bytes").unwrap();
        let error = owned_backups_using(root, &mut || Ok(()), |_| {
            reads += 1;
            Err(ToolError::io("present backup receipt", std::io::Error::from(std::io::ErrorKind::PermissionDenied)))
        })
        .unwrap_err();
        assert_eq!(error.code, ErrorCode::NoPermission);
        assert_eq!(reads, 1, "an uncertain present backup still propagates its ownership read error");
    }

    #[test]
    fn ownership_hashing_checks_cancellation_between_chunks() {
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        let bytes = vec![b'x'; 3 * 64 * 1024];
        std::fs::write(&backup, &bytes).unwrap();
        let proof = receipt(&backup, &bytes).unwrap();
        let mut file = std::fs::File::open(&backup).unwrap();
        let stop = CancelToken::default();
        let mut checks = 0;
        let error = matches_open_file(&backup, &mut file, &proof, &mut || {
            checks += 1;
            if checks == 3 {
                stop.cancel();
            }
            stop.check()
        })
        .unwrap_err();
        assert_eq!(error.code, ErrorCode::Cancelled);
        assert_eq!(file.stream_position().unwrap(), 64 * 1024, "cancellation stops before the second chunk");
        assert_eq!(owned_backups_with_cancel(directory.path(), &stop).unwrap_err().code, ErrorCode::Cancelled);
        assert_eq!(owns_open_backup_with_cancel(directory.path(), &backup, &mut file, &stop).unwrap_err().code, ErrorCode::Cancelled);
    }

    #[test]
    fn interrupted_publication_requires_the_staged_file_identity() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        let backup = root.join("feed.json.broken");
        let error = publish_using(root, &backup, b"complete original", || Err(ToolError::internal("interrupted before final receipt"))).unwrap_err();
        assert!(error.message.contains("interrupted"));
        assert!(!root.join("inbox/feed-backups/feed.json.broken.json").exists());
        assert_eq!(matching_copy(root, b"complete original").unwrap(), Some(backup.clone()));
        let retained = root.join("retained-original");
        std::fs::rename(&backup, &retained).unwrap();
        std::fs::write(&backup, b"complete original").unwrap();
        assert!(owned_backups(root).unwrap().is_empty(), "equal personal bytes in a different file are not the pending copy");
        assert!(matching_copy(root, b"complete original").unwrap().is_none());
        assert_eq!(std::fs::read(&backup).unwrap(), b"complete original");
        assert_eq!(std::fs::read(&retained).unwrap(), b"complete original");
    }

    #[test]
    fn a_reusable_copy_requires_its_receipt_source_and_current_contents() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        let backup = root.join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        assert!(matching_copy(root, b"original").unwrap().is_none(), "unrecorded identical bytes are still an unrelated entry");
        record(root, &backup, b"original").unwrap();
        assert_eq!(matching_copy(root, b"original").unwrap(), Some(backup.clone()));
        assert!(matching_copy(root, b"another source").unwrap().is_none());
        std::fs::write(&backup, b"personal").unwrap();
        assert!(matching_copy(root, b"original").unwrap().is_none(), "the receipt cannot own changed contents of the same length");
        std::fs::write(&backup, b"original").unwrap();
        let path = root.join("inbox/feed-backups/feed.json.broken.json");
        let mut newer: serde_json::Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        newer["version"] = serde_json::json!(99);
        let bytes = serde_json::to_vec(&newer).unwrap();
        std::fs::write(&path, &bytes).unwrap();
        assert!(matching_copy(root, b"original").unwrap().is_none(), "an unknown receipt never authorizes reuse");
        assert_eq!(std::fs::read(&path).unwrap(), bytes);
        assert_eq!(std::fs::read(&backup).unwrap(), b"original");
    }

    #[test]
    fn ownership_checks_the_open_file_instead_of_reopening_its_path() {
        use std::io::Read as _;
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        let backup = root.join("feed.json.broken");
        std::fs::write(&backup, b"personal content").unwrap();
        let mut personal = std::fs::File::open(&backup).unwrap();
        std::fs::rename(&backup, root.join("personal.txt")).unwrap();
        std::fs::write(&backup, b"generated backup").unwrap();
        record(root, &backup, b"generated backup").unwrap();

        assert!(!owns_open_backup(root, &backup, &mut personal).unwrap(), "the receipt at this path does not own the earlier open file");
        let mut bytes = Vec::new();
        personal.read_to_end(&mut bytes).unwrap();
        assert_eq!(bytes, b"personal content", "the same handle remains positioned for copying");
        let mut generated = std::fs::File::open(&backup).unwrap();
        assert!(owns_open_backup(root, &backup, &mut generated).unwrap());
    }

    #[test]
    fn unowned_backup_checks_rewind_the_copy_handle() {
        use std::io::Read as _;
        for with_receipt in [false, true] {
            let directory = tempfile::tempdir().unwrap();
            let root = directory.path();
            let backup = root.join("feed.json.broken");
            std::fs::write(&backup, b"generated backup").unwrap();
            if with_receipt {
                record(root, &backup, b"generated backup").unwrap();
            }
            std::fs::write(&backup, b"personal words with a different length").unwrap();
            let mut file = std::fs::File::open(&backup).unwrap();
            let mut prefix = [0u8; 4];
            file.read_exact(&mut prefix).unwrap();

            assert!(!owns_open_backup(root, &backup, &mut file).unwrap());

            let mut copied = Vec::new();
            file.read_to_end(&mut copied).unwrap();
            assert_eq!(copied, b"personal words with a different length", "missing receipt and length mismatch both reset the copy position");
        }
    }

    #[test]
    fn deleting_a_claimed_backup_leaves_a_new_public_entry() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        let backup = root.join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(root, &backup, b"original").unwrap();
        let selected = owned_backups(root).unwrap();
        let mut private = None;

        remove_after_claim(root, &selected, |original, claimed| {
            private = Some(claimed.parent().unwrap().to_path_buf());
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                assert_eq!(std::fs::metadata(claimed.parent().unwrap()).unwrap().permissions().mode() & 0o777, 0o700);
            }
            std::fs::write(original, b"Keep the new public entry").unwrap();
        })
        .unwrap();

        assert_eq!(std::fs::read(&backup).unwrap(), b"Keep the new public entry");
        assert!(!private.unwrap().exists(), "only the verified claimed file and its empty directory are removed");
    }

    #[test]
    fn changed_claims_are_restored_without_overwriting_another_entry() {
        for conflict in [false, true] {
            let directory = tempfile::tempdir().unwrap();
            let root = directory.path();
            let backup = root.join("feed.json.broken");
            std::fs::write(&backup, b"original").unwrap();
            record(root, &backup, b"original").unwrap();
            let selected = owned_backups(root).unwrap();
            let replacement = root.join("replacement");
            std::fs::write(&replacement, b"First personal replacement").unwrap();
            std::fs::rename(&replacement, &backup).unwrap();
            let mut preserved = None;

            let error = remove_after_claim(root, &selected, |original, claimed| {
                preserved = Some(claimed.to_path_buf());
                if conflict {
                    std::fs::write(original, b"Second personal replacement").unwrap();
                }
            })
            .unwrap_err();

            assert_eq!(error.code, ErrorCode::FileChanged);
            let preserved = preserved.unwrap();
            if conflict {
                assert_eq!(std::fs::read(&backup).unwrap(), b"Second personal replacement");
                assert_eq!(std::fs::read(&preserved).unwrap(), b"First personal replacement");
                assert!(error.remediation.unwrap().contains(preserved.to_string_lossy().as_ref()));
            } else {
                assert_eq!(std::fs::read(&backup).unwrap(), b"First personal replacement");
                assert!(!preserved.parent().unwrap().exists());
                assert!(error.remediation.unwrap().contains("restored"));
            }
        }
    }

    #[test]
    fn a_changed_directory_survives_this_and_later_project_deletion() {
        use crate::workspace::{TargetRef, Workspace};
        let directory = tempfile::tempdir().unwrap();
        let ws = Workspace::create(directory.path(), "Site", "A website", TargetRef::None).unwrap();
        let root = ws.root.clone();
        let backup = root.join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(&root, &backup, b"original").unwrap();
        let selected = owned_backups(&root).unwrap();
        std::fs::remove_file(&backup).unwrap();
        std::fs::create_dir(&backup).unwrap();
        std::fs::write(backup.join("notes.txt"), b"Keep the personal directory").unwrap();
        let mut preserved = None;

        let error = remove_after_claim(&root, &selected, |_, claimed| preserved = Some(claimed.to_path_buf())).unwrap_err();

        assert_eq!(error.code, ErrorCode::FileChanged);
        let preserved = preserved.unwrap();
        assert_eq!(std::fs::read(preserved.join("notes.txt")).unwrap(), b"Keep the personal directory");
        assert!(error.remediation.unwrap().contains(preserved.to_string_lossy().as_ref()));
        ws.delete().unwrap();
        assert!(!root.join(crate::workspace::MANIFEST).exists());
        assert_eq!(std::fs::read(preserved.join("notes.txt")).unwrap(), b"Keep the personal directory");
    }

    #[cfg(unix)]
    #[test]
    fn a_changed_link_is_preserved_without_following_its_target() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path().join("project");
        std::fs::create_dir(&root).unwrap();
        let backup = root.join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(&root, &backup, b"original").unwrap();
        let selected = owned_backups(&root).unwrap();
        let personal = directory.path().join("personal");
        std::fs::write(&personal, b"Keep the target").unwrap();
        std::fs::remove_file(&backup).unwrap();
        std::os::unix::fs::symlink(&personal, &backup).unwrap();
        let mut preserved = None;

        remove_after_claim(&root, &selected, |_, claimed| preserved = Some(claimed.to_path_buf())).unwrap_err();

        let preserved = preserved.unwrap();
        assert!(std::fs::symlink_metadata(&preserved).unwrap().file_type().is_symlink());
        assert_eq!(std::fs::read_link(&preserved).unwrap(), personal);
        assert_eq!(std::fs::read(&personal).unwrap(), b"Keep the target");
    }

    #[test]
    fn receipts_belong_to_one_unchanged_regular_backup() {
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        assert_eq!(owned_backups(directory.path()).unwrap().as_slice(), std::slice::from_ref(&backup));

        std::fs::write(&backup, b"personal").unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty(), "the same length doesn't establish ownership of new content");
        std::fs::remove_file(&backup).unwrap();
        std::fs::create_dir(&backup).unwrap();
        std::fs::write(backup.join("notes.txt"), "Keep this directory").unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty(), "a directory can never be a generated recovery file");
    }

    #[test]
    fn unknown_receipts_are_preserved_and_never_authorize_deletion() {
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        let path = directory.path().join("inbox/feed-backups/feed.json.broken.json");
        let original: serde_json::Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        let cases = [("version", serde_json::json!(99)), ("format", serde_json::json!("personal-data")), ("backup", serde_json::json!("../personal-file"))];
        for (field, value) in cases {
            let mut changed = original.clone();
            changed[field] = value;
            let bytes = serde_json::to_vec(&changed).unwrap();
            std::fs::write(&path, &bytes).unwrap();
            assert!(owned_backups(directory.path()).unwrap().is_empty(), "{field}");
            assert!(record(directory.path(), &backup, b"original").is_err(), "{field}");
            assert_eq!(std::fs::read(&path).unwrap(), bytes, "{field}: the unknown record is not overwritten");
        }
        std::fs::write(&path, b"unreadable receipt").unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty());
        assert!(record(directory.path(), &backup, b"original").is_err());
        assert_eq!(std::fs::read(&path).unwrap(), b"unreadable receipt");
    }

    #[test]
    fn concurrent_copies_keep_separate_receipts() {
        let directory = tempfile::tempdir().unwrap();
        std::thread::scope(|scope| {
            let writers: Vec<_> = ["feed.json.broken", "feed.json.broken.1"]
                .into_iter()
                .map(|name| {
                    let root = directory.path();
                    scope.spawn(move || {
                        let backup = root.join(name);
                        std::fs::write(&backup, name.as_bytes()).unwrap();
                        record(root, &backup, name.as_bytes()).unwrap();
                    })
                })
                .collect();
            for writer in writers {
                writer.join().unwrap();
            }
        });
        assert_eq!(owned_backups(directory.path()).unwrap().len(), 2);
    }

    #[test]
    fn a_failed_receipt_keeps_the_original_conversation() {
        use crate::workspace::{TargetRef, Workspace};
        let directory = tempfile::tempdir().unwrap();
        let ws = Workspace::create(directory.path(), "Site", "A website", TargetRef::None).unwrap();
        let records = ws.root.join("inbox/feed-backups");
        std::fs::create_dir_all(&records).unwrap();
        let path = records.join("feed.json.broken.json");
        let future = br#"{"format":"craft-anything.feed-backup","version":99,"backup":"feed.json.broken","future":true}"#;
        std::fs::write(&path, future).unwrap();
        let source = ws.root.join(crate::feed::FEED_FILE);
        std::fs::write(&source, b"damaged conversation").unwrap();
        let mut feed = crate::feed::load(&ws);

        assert!(crate::feed::save(&ws.root, &mut feed).is_err());

        assert_eq!(std::fs::read(&source).unwrap(), b"damaged conversation");
        assert_eq!(std::fs::read(&path).unwrap(), future);
        assert!(!ws.root.join("feed.json.broken").exists(), "the unsuccessful new copy is cleaned up");
    }

    #[cfg(unix)]
    #[test]
    fn receipts_do_not_follow_backup_or_receipt_links() {
        use std::os::unix::fs::symlink;
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        let personal = directory.path().join("personal");
        std::fs::write(&personal, b"original").unwrap();
        std::fs::remove_file(&backup).unwrap();
        symlink(&personal, &backup).unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty());
        std::fs::remove_file(&backup).unwrap();
        std::fs::write(&backup, b"original").unwrap();

        let path = directory.path().join("inbox/feed-backups/feed.json.broken.json");
        let saved = directory.path().join("personal-receipt.json");
        std::fs::rename(&path, &saved).unwrap();
        symlink(&saved, &path).unwrap();
        let original = std::fs::read(&saved).unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty());
        assert!(record(directory.path(), &backup, b"original").is_err());
        assert_eq!(std::fs::read(&saved).unwrap(), original);
    }
